const works=[{src:'assets/chrome-candle.png',title:'Still here',description:'一个打成结的愿望。',name:'存在之结'},{src:'assets/wild-wish.svg',title:'Wild wish',description:'愿你永远有点不合时宜。',name:'野生愿望'},{src:'assets/little-sun.svg',title:'Little sun',description:'你也有自己的引力。',name:'小小太阳'}];
const blessings={birthday:'生日快乐。很高兴你在这个世界上。',wild:'愿你永远有点不合时宜。',orbit:'又绕太阳一圈，还好我们遇见了。',none:''};
let selected=Number(document.body.dataset.default||0);let handle='';
const dialog=document.querySelector('dialog'),content=document.querySelector('#dialog-content');let origin;
function toast(text){const t=document.querySelector('.toast');t.textContent=text;t.hidden=false;clearTimeout(window.tt);window.tt=setTimeout(()=>t.hidden=true,3000)}
function open(){origin=document.activeElement;if(!dialog.open)dialog.showModal()}
function close(){dialog.close();origin?.focus()}
document.querySelector('.close').onclick=close;
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
function select(i){selected=i;document.querySelectorAll('[data-feature-image]').forEach(im=>{im.src=works[i].src;im.alt=works[i].name+'，概念作品'});document.querySelectorAll('[data-title]').forEach(el=>el.textContent=works[i].title);document.querySelectorAll('[data-description]').forEach(el=>el.textContent=works[i].description);document.querySelectorAll('[data-select]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.select)===i)))}
function choose(){content.innerHTML='<div class="modal"><h2 id="dialog-heading">哪个愿望，像他？</h2><div class="pick-list">'+works.map((w,i)=>`<button class="pick-item" data-choose="${i}"><img src="${w.src}" alt="${w.name}概念作品"><div><strong>${w.title}</strong><small>${w.description}</small></div></button>`).join('')+'</div><p class="help" style="margin-top:20px!important">本轮概念作品，仅用于设计探索。</p></div>';open();content.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>{select(Number(b.dataset.choose));close()})}
function prepare(){const main=document.querySelector('#main-recipient');handle=main?main.value:handle;const w=works[selected];content.innerHTML=`<div class="modal form-layout"><div class="form-art"><img src="${w.src}" alt="${w.name}"></div><div class="form-copy"><h2 id="dialog-heading">这次，只送给谁？</h2><p>${w.title}</p><form id="gift-form" novalidate><label class="field-label" for="recipient">朋友的 .ai 名字</label><input class="full" id="recipient" maxlength="40" placeholder="satoshi.ai" autocomplete="off" aria-describedby="recipient-help recipient-error"><p id="recipient-help" class="help">3–15 位英文字母或数字，可带 .ai。此处只做格式检查。</p><label class="field-label" for="blessing">留下一句祝福</label><select id="blessing"><option value="birthday">生日快乐。很高兴你在这个世界上。</option><option value="wild">愿你永远有点不合时宜。</option><option value="orbit">又绕太阳一圈，还好我们遇见了。</option><option value="none">不附祝福</option></select><p class="help">演示署名 jimu.ai。作品尚未定价。</p><p id="recipient-error" class="error" role="alert"></p><div class="form-actions"><button class="primary">预览这份心意</button></div><p class="help">仅预览，不连接钱包，不付款，不发送 NFT。</p></form></div></div>`;document.querySelector('#recipient').value=handle;open();document.querySelector('#gift-form').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#recipient');const h=input.value.trim().toLowerCase().replace(/\.ai$/,'');if(!/^[a-z0-9]{3,15}$/.test(h)){input.setAttribute('aria-invalid','true');document.querySelector('#recipient-error').textContent='请输入 3–15 位字母或数字的名字。';input.focus();return}handle=h+'.ai';receipt(selected,handle,document.querySelector('#blessing').value)}}
function receipt(id,to,bl){const name=/^[a-z0-9]{3,15}\.ai$/.test(to)?to:'friend.ai';const wish=Object.hasOwn(blessings,bl)?blessings[bl]:blessings.birthday;content.innerHTML=`<div class="receipt"><p class="small-title">礼物页面预览，没有发生真实赠送。</p><h2 id="dialog-heading">给 ${name}。</h2><p>很高兴，你在。</p><img src="${works[id].src}" alt="${works[id].name}概念作品"><h3>${works[id].title}</h3><blockquote>${wish}</blockquote><p class="meta">来自演示身份 jimu.ai<br>这是一份界面预览，作品尚未铸造或送达。</p><button class="primary" id="share">复制预览链接</button><button class="secondary" id="again">再挑一份</button></div>`;document.querySelector('#share').onclick=async()=>{const url=new URL(location.href);url.searchParams.set('gift',String(id));url.searchParams.set('to',name);url.searchParams.set('wish',Object.keys(blessings).includes(bl)?bl:'birthday');try{await navigator.clipboard.writeText(url.href);toast('已复制本地演示链接。')}catch{history.replaceState(null,'',url.href);toast('请复制浏览器地址栏中的链接。')}};document.querySelector('#again').onclick=choose;open()}
document.querySelectorAll('[data-choose-open]').forEach(b=>b.onclick=choose);document.querySelectorAll('[data-prepare]').forEach(b=>b.onclick=prepare);document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{if(b.dataset.dragged==='true'){b.dataset.dragged='false';return}select(Number(b.dataset.select))});document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>select((selected+1)%works.length));
document.querySelectorAll('[data-wallet]').forEach(b=>b.onclick=()=>{b.textContent='jimu.ai（演示）';toast('仅切换为演示身份，没有连接真实钱包。')});
document.querySelectorAll('[data-about]').forEach(b=>b.onclick=()=>{content.innerHTML='<div class="modal"><h2 id="dialog-heading">让心意，有自己的形状。</h2><p>平台与签约艺术家提供作品。用朋友的 .ai 名字，准备一份生日艺术礼物。</p><p style="margin-top:20px">直接送达、赠送后不可转让是产品的设计目标。当前页面仅探索视觉与交互，没有真实钱包、支付或合约接入。</p></div>';open()});
// Movable specimens retain native button activation. Pointer motion is bounded to the stage.
document.querySelectorAll('[data-draggable]').forEach(el=>{let drag=null;el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const stage=el.parentElement.getBoundingClientRect(),r=el.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:r.left-stage.left,top:r.top-stage.top,moved:false};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>7)drag.moved=true;if(drag.moved){const maxX=el.parentElement.clientWidth-el.offsetWidth,maxY=el.parentElement.clientHeight-el.offsetHeight;el.style.left=Math.max(0,Math.min(maxX,drag.left+dx))+'px';el.style.top=Math.max(0,Math.min(maxY,drag.top+dy))+'px';el.style.transform='rotate(0deg)';}});el.addEventListener('pointerup',()=>{if(drag?.moved)el.dataset.dragged='true';drag=null});el.addEventListener('pointercancel',()=>drag=null)});
const q=new URLSearchParams(location.search);if(['0','1','2'].includes(q.get('gift'))){receipt(Number(q.get('gift')),q.get('to')||'friend.ai',q.get('wish')||'birthday')}
